  class NomCausasExclusionNomina extends BaseNomCausasExclusionNomina
  {

    /**
     * Obtener un listado de los datos de las causas de exclusión.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de las causas de exclusión.
     */
    public static function obtenerListadoCausasExclusionNomina($inicio = 0, $limite = 1000)
    {
      //Devolviendo el listado de las causas de exclusión en forma de arreglo.
      $query = new Doctrine_Query ();
      $result = (($inicio != null) and ($limite != null))?
      $query->from('NomCausasExclusionNomina')
        ->limit($limite)
        ->offset($inicio)
        ->orderBy('denominacion')
        ->fetchArray():
        $query->from('NomCausasExclusionNomina')
          ->orderBy('denominacion')
          ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de las causas de exclusión.
     *
     * @return int      Cantidad total de las causas de exclusión.
     */
    public static function obtenerCantidadTotalCausasExclusionNomina()
    {

      //Devolviendo la cantidad total de las causas de exclusión.
      return Doctrine_Query::create()->select('COUNT(idcausaexclusion) AS cantidad')
        ->from('NomCausasExclusionNomina')
        ->fetchOne()
        ->cantidad;
    }

    /**
     * Obtener la causa de exclusión dado el identificador.
     *
     * @param int $idcausaexclusion Identificador de la causa de exclusión.
     *
     * @return NomCausasExclusionNomina        Objeto causa de exclusión (clase del dominio).
     */
    public static function obtenerObjCausasExclusionNominaDadoId($idcausaexclusion)
    {
      return Doctrine::getTable('NomCausasExclusionNomina')->find($idcausaexclusion);
    }

    /**
     * Obtener si existe la causa de exclusión a partir de la denominación.
     *
     * @param int $idcausaexc Identificador de la causa de exclusión.
     * @param string $denom Denominación de la causa de exclusión.
     *
     * @return boolean          Si existe la causa de exclusión.
     */
    public static function existeCausaExclusion($idcausaexc, $denom)
    {

      $query = Doctrine_Query::create()->select('COUNT(idcausaexclusion) AS cantidad')
        ->from('NomCausasExclusionNomina')
        ->where("denominacion ilike '$denom'");
      if (!empty($idcausaexc)) {
        $query->addWhere('idcausaexclusion <> ?', $idcausaexc);
      }

      return $query->fetchOne()->cantidad;
    }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idcausaexclusion = null)
    {
      try {
        $query = Doctrine_Query::create();
        $query->from('NomCausasExclusionNomina')
          ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
          ->andWhere("denominacion ilike '$denom'");
        if (!empty($idcausaexclusion)) {
          $query->andWhere("idcausaexclusion <> ?", $idcausaexclusion);
        }
        $result = $query->count();
        if ($result > 0) {
          return true;
        } else {
          return false;
        }
      } catch (Doctrine_Exception $e) {
        throw $e;
      }
    }
  }
